{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.Base_stock_store_analytics as WITH store_master AS ( SELECT marketplace_mapped, ANY_VALUE(cluster) AS cluster, ANY_VALUE(state) AS state, ANY_VALUE(city) AS city FROM snitch_db.maplemonk.offline_master GROUP BY marketplace_mapped ), table_1 AS ( SELECT p.marketplace_mapped AS store_name, upper(s.cluster) as cluster, UPPER(s.state) as state, UPPER(s.city) as city, upper(p.l_1_category) AS l1_category, REPLACE(upper(p.category), \'T-SHIRTS\', \'TSHIRTS\') AS category, NULLIF(upper(p.meta_1), \'NA\') AS meta_1, NULLIF(UPPER(REPLACE(p.meta_2, \'Embroided\', \'Embroidered\')), \'NA\') AS meta_2, NULLIF(upper(p.meta_3), \'NA\') AS meta_3, TRY_TO_NUMBER(REPLACE(p.mar, \',\', \'\')) AS planned_base_stock FROM snitch_db.maplemonk.base_stock_planned p LEFT JOIN store_master s ON UPPER(TRIM(p.marketplace_mapped)) = UPPER(TRIM(s.marketplace_mapped)) ), table_2_base AS ( SELECT upper(q.marketplace_mapped) AS store_name, UPPER(q.cluster) AS cluster, UPPER(q.state) AS state, UPPER(q.city) AS city, upper(p.l1_category) as l1_category, CASE WHEN UPPER(TRIM(p.category)) = \'T-SHIRTS\' THEN \'TSHIRTS\' WHEN UPPER(TRIM(p.category)) = \'SWEATER\' THEN \'SWEATERS\' WHEN UPPER(TRIM(p.category)) = \'JACKET\' THEN \'JACKETS\' ELSE UPPER(TRIM(p.category)) END AS category, upper(p.meta1) as meta1, CASE WHEN REPLACE(UPPER(TRIM(p.category)), \'-\', \'\') = \'TSHIRTS\' THEN UPPER(p.meta2) ELSE upper(p.meta3) END AS meta2, CASE WHEN REPLACE(UPPER(TRIM(p.category)), \'-\', \'\') = \'TSHIRTS\' THEN upper(p.meta3) ELSE NULL END AS meta3, q.inventory, q.jit_qty FROM snitch_db.maplemonk.category_overall_data p LEFT JOIN snitch_db.maplemonk.offline_master q ON ( CASE WHEN UPPER(TRIM(p.sku_group)) LIKE \'SN%\' OR UPPER(TRIM(p.sku_group)) LIKE \'BP%\' THEN UPPER(TRIM(p.sku_group)) WHEN UPPER(TRIM(p.sku_group)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(p.sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(p.sku_group)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(p.sku_group::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(p.sku_group)) END END ) = ( CASE WHEN UPPER(TRIM(q.sku_group)) LIKE \'SN%\' OR UPPER(TRIM(q.sku_group)) LIKE \'BP%\' THEN UPPER(TRIM(q.sku_group)) WHEN UPPER(TRIM(q.sku_group)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(q.sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(q.sku_group)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(q.sku_group::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(q.sku_group)) END END ) ), table_2 AS ( SELECT store_name, ANY_VALUE(cluster) AS cluster, ANY_VALUE(state) AS state, ANY_VALUE(city) AS city, l1_category, category, CASE WHEN LOWER(TRIM(l1_category)) = \'luxe\' THEN NULL ELSE meta1 END AS meta1, CASE WHEN LOWER(TRIM(l1_category)) = \'luxe\' THEN NULL ELSE meta2 END AS meta2, CASE WHEN LOWER(TRIM(l1_category)) = \'luxe\' THEN NULL ELSE meta3 END AS meta3, SUM(inventory) AS actual_base_stock, SUM(jit_qty) as total_jit_qty, SUM(jit_qty) + SUM(inventory) AS actual_with_jit FROM table_2_base WHERE store_name IS NOT NULL AND l1_category IS NOT NULL AND LOWER(TRIM(l1_category)) IN (\'snitch\',\'luxe\',\'plus\') GROUP BY store_name, l1_category, category, CASE WHEN LOWER(TRIM(l1_category)) = \'luxe\' THEN NULL ELSE meta1 END, CASE WHEN LOWER(TRIM(l1_category)) = \'luxe\' THEN NULL ELSE meta2 END, CASE WHEN LOWER(TRIM(l1_category)) = \'luxe\' THEN NULL ELSE meta3 END ), current_inventory_sku_map AS ( SELECT CASE WHEN UPPER(TRIM(p.sku_group)) LIKE \'SN%\' OR UPPER(TRIM(p.sku_group)) LIKE \'BP%\' THEN UPPER(TRIM(p.sku_group)) WHEN UPPER(TRIM(p.sku_group)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(p.sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(p.sku_group)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(p.sku_group::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(p.sku_group)) END END AS sku_group, UPPER(p.l1_category) AS l1_category, CASE WHEN UPPER(TRIM(p.category)) = \'T-SHIRTS\' THEN \'TSHIRTS\' WHEN UPPER(TRIM(p.category)) = \'SWEATER\' THEN \'SWEATERS\' WHEN UPPER(TRIM(p.category)) = \'JACKET\' THEN \'JACKETS\' ELSE UPPER(TRIM(p.category)) END AS category, UPPER(p.meta1) AS meta1, CASE WHEN REPLACE(UPPER(TRIM(p.category)), \'-\', \'\') = \'TSHIRTS\' THEN UPPER(p.meta2) ELSE UPPER(p.meta3) END AS meta2, CASE WHEN REPLACE(UPPER(TRIM(p.category)), \'-\', \'\') = \'TSHIRTS\' THEN UPPER(p.meta3) ELSE NULL END AS meta3 FROM snitch_db.maplemonk.category_overall_data p QUALIFY ROW_NUMBER() OVER ( PARTITION BY CASE WHEN UPPER(TRIM(p.sku_group)) LIKE \'SN%\' OR UPPER(TRIM(p.sku_group)) LIKE \'BP%\' THEN UPPER(TRIM(p.sku_group)) WHEN UPPER(TRIM(p.sku_group)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(p.sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(p.sku_group)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(p.sku_group::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(p.sku_group)) END END ORDER BY p.sku_group ) = 1 ), unicommerce_sku_inventory AS ( SELECT CASE WHEN UPPER(TRIM(\"Item SkuCode\")) LIKE \'SN%\' OR UPPER(TRIM(\"Item SkuCode\")) LIKE \'BP%\' THEN UPPER(TRIM(\"Item SkuCode\")) WHEN UPPER(TRIM(\"Item SkuCode\")) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\"::STRING, \'^[^-]+-[^-]+-[^-]+\'))) WHEN UPPER(TRIM(\"Item SkuCode\")) LIKE \'4C%\' THEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\"::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(\"Item SkuCode\")) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\"::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(\"Item SkuCode\")) END END AS sku_group, SUM( CASE WHEN UPPER(TRIM(u.facility)) = \'SAPL-NORTH-TAURU\' THEN u.inventory ELSE 0 END ) AS north_inv, SUM( CASE WHEN UPPER(TRIM(u.facility)) IN (\'SAPL-WH1\',\'SAPL-WH2\') THEN u.inventory ELSE 0 END ) AS south_inv FROM snitch_db.maplemonk.unicommerce_live_inventory u GROUP BY 1 ), current_inventory_final AS ( SELECT m.l1_category, m.category, CASE WHEN LOWER(TRIM(m.l1_category)) = \'luxe\' THEN NULL ELSE m.meta1 END AS meta1, CASE WHEN LOWER(TRIM(m.l1_category)) = \'luxe\' THEN NULL ELSE m.meta2 END AS meta2, CASE WHEN LOWER(TRIM(m.l1_category)) = \'luxe\' THEN NULL ELSE m.meta3 END AS meta3, SUM(COALESCE(u.north_inv, 0)) AS north_inv, SUM(COALESCE(u.south_inv, 0)) AS south_inv FROM current_inventory_sku_map m LEFT JOIN unicommerce_sku_inventory u ON m.sku_group = u.sku_group WHERE m.l1_category IS NOT NULL AND LOWER(TRIM(m.l1_category)) IN (\'snitch\',\'luxe\',\'plus\') GROUP BY m.l1_category, m.category, CASE WHEN LOWER(TRIM(m.l1_category)) = \'luxe\' THEN NULL ELSE m.meta1 END, CASE WHEN LOWER(TRIM(m.l1_category)) = \'luxe\' THEN NULL ELSE m.meta2 END, CASE WHEN LOWER(TRIM(m.l1_category)) = \'luxe\' THEN NULL ELSE m.meta3 END ) SELECT COALESCE(t1.store_name, t2.store_name) AS store_name, COALESCE(t1.cluster, t2.cluster) AS cluster, COALESCE(t1.state, t2.state) AS state, COALESCE(t1.city, t2.city) AS city, UPPER(COALESCE(t1.l1_category, t2.l1_category)) AS l1_category, UPPER(COALESCE(t1.category, t2.category)) AS category, UPPER(COALESCE(t1.meta_1, t2.meta1)) AS meta_1, upper(COALESCE(t1.meta_2, t2.meta2)) AS meta_2, upper(COALESCE(t1.meta_3, t2.meta3)) AS meta_3, c.north_inv, c.south_inv, t1.planned_base_stock, t2.actual_base_stock, COALESCE(t1.planned_base_stock, 0) - COALESCE(t2.actual_base_stock, 0) AS delta_planned_actual, t2.total_jit_qty, t2.actual_with_jit, COALESCE(t1.planned_base_stock, 0) - COALESCE(t2.actual_with_jit, 0) AS delta_planned_actual_jit, FROM table_1 t1 FULL OUTER JOIN table_2 t2 ON UPPER(TRIM(COALESCE(t1.store_name, \'\'))) = UPPER(TRIM(COALESCE(t2.store_name, \'\'))) AND UPPER(TRIM(COALESCE(t1.l1_category, \'\'))) = UPPER(TRIM(COALESCE(t2.l1_category, \'\'))) AND UPPER(TRIM(COALESCE(t1.category, \'\'))) = UPPER(TRIM(COALESCE(t2.category, \'\'))) AND UPPER(TRIM(COALESCE(t1.meta_1, \'\'))) = UPPER(TRIM(COALESCE(t2.meta1, \'\'))) AND UPPER(TRIM(COALESCE(t1.meta_2, \'\'))) = UPPER(TRIM(COALESCE(t2.meta2, \'\'))) AND UPPER(TRIM(COALESCE(t1.meta_3, \'\'))) = UPPER(TRIM(COALESCE(t2.meta3, \'\'))) LEFT JOIN current_inventory_final c ON UPPER(TRIM(COALESCE(t1.l1_category, t2.l1_category, \'\'))) = UPPER(TRIM(COALESCE(c.l1_category, \'\'))) AND UPPER(TRIM(COALESCE(t1.category, t2.category, \'\'))) = UPPER(TRIM(COALESCE(c.category, \'\'))) AND UPPER(TRIM(COALESCE(t1.meta_1, t2.meta1, \'\'))) = UPPER(TRIM(COALESCE(c.meta1, \'\'))) AND UPPER(TRIM(COALESCE(t1.meta_2, t2.meta2, \'\'))) = UPPER(TRIM(COALESCE(c.meta2, \'\'))) AND UPPER(TRIM(COALESCE(t1.meta_3, t2.meta3, \'\'))) = UPPER(TRIM(COALESCE(c.meta3, \'\'))) WHERE COALESCE(t1.l1_category, t2.l1_category) IS NOT NULL and COALESCE(t1.store_name, t2.store_name) not in (\'SNITCH - WH - MAHARASTRA\',\'SNITCH - WH - NORTH\',\'SUVIDHA STORES - SONIPAT\',\'SNITCH - FOCO - MAPLE MYSURU\',\'SNITCH - COCO - HLP GALLERIA MALL\')",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            